    "transportInfo.water.transport": "Środek transportu",
    "transportInfo.water.miles": "Mile na dzień",
    "transportInfo.water.hours": "Godz. na dzień",
    "transportInfo.water.speed": "Mile/godz.",
    "transportInfo.water.downstream": "z prądem",
