    "transportInfo.water.nonStop": "bez odpoczynku",
    "transportInfo.path.Reichsstrasse": "Gościniec cesarski",
    "transportInfo.path.Strasse": "Gościniec",
    "transportInfo.path.Weg": "Droga",
    "transportInfo.path.Pfad": "Ścieżka",
